{
  "findings": [
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that live, unmoderated voice and text chat can expose children to random strangers and profanity.",
      "stance": "risk",
      "quote": "Live, unmoderated chat is possible between users in the console and PC versions of Fortnite: Battle Royale. Options include voice chat and on-screen text chat. This exposes players to random strangers and the likelihood of profanity."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "The game encourages frequent purchases of new content through seasonal Battle Passes.",
      "stance": "risk",
      "quote": "Seasons seem to update approximately every 10–12 weeks, and 10 seasons make up a chapter. You'll begin to see clues to the updates during the current season, usually to encourage players to purchase the next season's Battle Pass."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that the platform collects user data and may share it with third parties for advertising, but the policy does not specify deletion options.",
      "stance": "neutral",
      "quote": "The platform's live events, which are often tied to a feature in the game, can attract tens of millions of viewers (not just players) around the world."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate appears to work in practice, as the game is marketed to older audiences and requires an account.",
      "stance": "mitigation",
      "quote": "You can play Fortnite on the latest game consoles (PlayStation, Xbox, and Switch), computers (Mac and Windows), and Android mobile devices."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that live events such as concerts and promotional trailers are family-friendly and suitable for children.",
      "stance": "neutral",
      "quote": "Some of these events are scheduled and some are spontaneous. If your kid's into Fortnite, they'll probably hear the buzz and want to tune in. Events tend to be family-friendly and are listed in the [news section of the Fortnite site](https://www.epicgames.com/fortnite/en-US/news)."
    }
  ]
}
